{
  "documentVersion": 2,
  "slug": "studio-welcome",
  "title": "Studio welcome",
  "summary": "Welcome people to a space with a name and a helpful message.",
  "sims": [
    {
      "key": "welcome",
      "title": "Welcome",
      "htmlFile": "welcome.html"
    }
  ],
  "inputs": [
    {
      "kind": "text",
      "key": "place_name",
      "label": "What is your space called?",
      "sample": "The Corner Studio"
    }
  ],
  "skills": [
    {
      "file": "skills/welcome-setup/SKILL.md",
      "for": [
        "steward"
      ],
      "files": [
        "references/placement.md"
      ]
    }
  ],
  "successCheck": "The welcome Sim shows the owner’s space name.",
  "devices": [
    {
      "key": "welcome_screen",
      "label": "Welcome screen",
      "purpose": "Show the welcome Sim where visitors arrive.",
      "displaySim": "welcome",
      "optional": true,
      "fulfillment": [
        "open_url",
        "screen",
        "hardware_later"
      ]
    }
  ]
}
